buttonsRow.onClick:
const form = this.getFormRef();
const goEmr = (row) => {
  form.$examTran = row;                                  // opd_card อ่านตอน mount แรก (lazy tab)
  const card = form.getFieldRef('opd_card');
  if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(row);

  const tab = form.getFieldRef('main_app');
  if (tab) tab.activeTabName = 'tab_pane_41691';
};
const st = dataRow.vtran_status;
if (st === 'in_progress') { goEmr(dataRow); return; }
if (st !== 'called') { this.alert('เริ่มตรวจได้เฉพาะคิวที่เรียกแล้ว', 'warning'); return; }
const api = form.userState;
api.runProcess('6a4f852422f95f21b606d9a3', { tran_id: String(dataRow._id), action: 'start' }, (res) => {
  const d = res.data || {};
  if (!d.success) { this.alert(d.message || 'เริ่มตรวจไม่สำเร็จ', 'warning'); return; }
  this.alert('เริ่มตรวจคิว ' + d.queue_label, 'success');
  this.getFieldEditor().handleRefresh();
    // process เพิ่ง stamp start_at ใน DB — dataRow เป็น snapshot เก่า ต้อง patch ก่อนส่งเข้าการ์ด ไม่งั้น timer ขึ้น --:--
  goEmr({ ...dataRow, vtran_status: 'in_progress', start_at: this.dayjs().format('YYYY-MM-DD HH:mm:ss') });

}, (err) => this.alert(String((err && err.message) || err), 'error'));

const st = dataRow.vtran_status;
const action = st === 'called' ? 'skip' : (st === 'skipped' ? 'recall' : null);
if (!action) { this.alert('ข้าม/เรียกกลับได้เฉพาะคิวสถานะ "เรียกแล้ว" หรือ "ข้าม"', 'warning'); return; }
const api = this.getFormRef().userState;
api.runProcess('6a4b9451ac48023662b1b42b', { tran_id: String(dataRow._id), action: action }, (res) => {
  const d = res.data || {};
  if (!d.success) { this.alert(d.message || 'ทำรายการไม่สำเร็จ', 'warning'); return; }
  this.alert((action === 'skip' ? 'ข้ามคิว ' : 'เรียกกลับเข้าแถว ') + d.queue_label, 'success');
  this.getFieldEditor().handleRefresh();
}, (err) => this.alert(String((err && err.message) || err), 'error'));

