s.historyByVisit = () => {
  try {
    const map = {}
    const addRec = (rec, kind) => {
      if (!rec || !rec.vid || !rec.vid.value) return
      const vid = String(rec.vid.value)
      if (!map[vid]) {
        map[vid] = {
          visitId: vid,
          visitDate: rec.vid.visit_date || (rec.created_at || '').slice(0, 10),
          vn: rec.vid.vn || '-',
          vs: null,
          bmi: null,
          ts: rec.created_at || ''
        }
      }
      map[vid][kind] = rec
      if (String(rec.created_at || '') > map[vid].ts) map[vid].ts = rec.created_at
    }
    ;(s.vsHistory || []).forEach((r) => addRec(r, 'vs'))
    ;(s.bmiHistory || []).forEach((r) => addRec(r, 'bmi'))
    return Object.values(map).sort((a, b) => String(b.ts).localeCompare(String(a.ts)))   // ใหม่สุดก่อน
  } catch (e) {
    console.error('[opd_card] historyByVisit failed:', e)
    return []
  }
}

