options.onCreated:
const s = this.vueState
const field = this

// ★ แทนด้วย _id ของ process disease_registry_list ใน API Factory
const REG_PROCESS = '6a51a09c6e185ae01ab5bb4d'

s.regList = []
s.regLoading = false
s.regPid = null      // person _id ปัจจุบัน — เซ็ตผ่าน s.load จาก opd_card
s.regPidRef = null   // ref ผู้ป่วยจาก visit (hn, ชื่อ) — ใช้ประกอบ joiner ตอน Add

// form id อ้างอิงในระบบ — ใช้เลือกว่า parentId ควรเป็น visit หรือ person
const VISIT_FORM = '6a40fdec4b6dfdf45acbfbce'
const PERSON_FORM = '6a37d3bd4cfbfdbe257fc912'

s.regVid = null   // visit _id ปัจจุบัน — มาจาก opd_card

// เรียกจาก opd_card.setTran — pattern เดียวกับ consult_box.load
s.load = (personId, pidRef, visitId) => {
  s.regPid = personId || null
  s.regPidRef = pidRef || null
  s.regVid = visitId || null
  s.regList = []
  if (!s.regPid) return
  const form = field.getFormRef()
  if (!form) return
  s.regLoading = true
  form.userState.runProcess(REG_PROCESS, { person_id: s.regPid, visit_id: s.regVid }, (res) => {
    const d = res.data || {}
    s.regList = d.items || []
    s.regLoading = false
  }, (err) => {
    s.regLoading = false
    field.alert('โหลดทะเบียนโรคไม่สำเร็จ: ' + ((err && err.message) || err), 'error')
  })
}

// badge ของแถว: match สถานะกับ status_options — ไม่เจอ → เทา + ค่า raw
s.regStatusOf = (item) => {
  if (!item.has_record) return null
  const raw = item.latest ? item.latest.status : null
  const hit = (item.status_options || []).find((o) => String(o.op_value) === String(raw))
  if (hit) return { label: hit.op_label, color: hit.op_color || 'info' }
  return { label: (raw === null || raw === undefined) ? '-' : String(raw), color: 'info' }
}


// parentId ที่ต้องส่งให้ฟอร์มเป้าหมาย ตาม parent ที่ฟอร์มนั้นผูก
s.regParentOf = (item) => {
  if (item.parent_form === VISIT_FORM) return s.regVid ? String(s.regVid) : null
  if (item.parent_form === PERSON_FORM) return s.regPid ? String(s.regPid) : null
  return null
}

// เปิด record ล่าสุด
s.openReg = (item) => {
  const form = field.getFormRef()
  if (!form) return
  const dataId = item.latest ? String(item.latest.data_id) : null
  form.openForm(item.target_form, dataId, s.regParentOf(item), null, {
    afterSaveCallback: () => { form.subFormClose(); s.load(s.regPid, s.regPidRef, s.regVid) }
  })
}

// เพิ่ม record ใหม่ — joiner โหลดจาก parentId เอง ไม่ต้องประกอบ initData
s.addReg = (item) => {
  const form = field.getFormRef()
  if (!form || !s.regPid) return
  const parentId = s.regParentOf(item)
  if (item.parent_form && !parentId) { field.alert('ไม่พบ visit ปัจจุบัน', 'warning'); return }
  form.openForm(item.target_form, null, parentId, null, {
    afterSaveCallback: () => { form.subFormClose(); s.load(s.regPid, s.regPidRef, s.regVid) }
  })
}

options.onMounted:
const field = this
const s = this.vueState
// เคสแท็บ EMR mount หลังกด EMR จากคิวแล้ว → ดึง tran จาก form เอง (แบบ opd_card)
setTimeout(() => {
  const form = field.getFormRef()
  const tran = form && form.$examTran
  const personId = (tran && tran.vid && tran.vid.xtbxlv1_xfx_id) ? String(tran.vid.xtbxlv1_xfx_id) : null
    s.load(
    personId,
    (tran && tran.vid && tran.vid.pid) || null,
    (tran && tran.vid && tran.vid.value) ? String(tran.vid.value) : null
  )

}, 0)

options.onCreated:
/**
 * order_card · onCreated — การ์ด "ใบสั่งยา" ในหน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488)
 *
 * หน้าที่: ทางเข้า "สั่งยา" ทั้งหมดของหน้า EMR รวมอยู่ที่การ์ดนี้ที่เดียว
 *   ① ปุ่ม "+ สั่งยา" (ใบใหม่)  ② เห็นใบที่บันทึกไปแล้วของวิสิทนี้  ③ กดกลับเข้าไปแก้ใบร่างเดิม
 *   ไม่มีการ์ดนี้ = ใบร่างหายเข้า DB · กดสั่งยาอีกครั้งได้ใบใหม่เรื่อย ๆ แทนที่จะแก้ใบเดิม
 *
 * วางที่: grid_col56484 — 🔴 แทนที่ button-ui `button_ui85075` เดิม (พี่สั่งย้ายปุ่มเข้าการ์ด 2026-08-04)
 *   ⇒ ประกอบ patient context ที่นี่ที่เดียว ไม่ต้องมีสองชุดให้แก้ให้ตรงกัน
 *   (ไฟล์ปุ่มเดิม emr-drug-order-button.js เก็บไว้อ้างอิงเท่านั้น ไม่ได้ใช้แล้ว)
 * โหลดข้อมูล: process cpoe-order-list (อ่านอย่างเดียว)
 *
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 * 🔴 การ์ดนี้ **ไม่ query ข้อมูลคนไข้เอง** — หยิบจาก opd_card ที่โหลดไว้แล้ว (แหล่งเดียวกับปุ่มสั่งยา)
 *    ระดับ warn/danger ของ vital ตัดสินที่ opd_card ที่เดียว ไม่งั้นสองจอเตือนคนละแบบ
 */

const s = this.vueState;
const field = this;

const DRUG_ORDER_FORM_ID = '6a70b8cd74be9b0d6e2dca74'; // Drug Order (form_ui)
const LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list
const SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send (draft → sent)
const VISIT_PROVIDER = '6a40fdec4b6dfdf45acbfbce'; // ฟอร์ม Visit → zdata_visit

/* ══ state ════════════════════════════════════════════════════════════════ */
s.ordList = [];
s.ordLoading = false;
s.ordErr = '';
s.ordVid = null; // visit _id ปัจจุบัน — เซ็ตผ่าน ordLoad จาก opd_card
s.ordTran = null; // Visit Tran ทั้งแถว (ใช้ประกอบ patient context ตอนเปิดจอสั่งยา)
s.ordOpenRow = {};
s.ordDirty = false; // จอสั่งยาแตะใบใน DB แล้วหรือยัง — ตัวตัดสินว่าตอนปิด popup ต้องโหลดใหม่ไหม
s.ordSending = {}; // order_id ที่กำลังส่ง — กันกดรัวระหว่างรอ process
s.ordBlocks = {}; // order_id → คำเตือนระดับห้ามสั่งที่ตีกลับมา (แสดงในการ์ด ไม่ใช่ alert ที่หายไป)
s.ordOvrId = ''; // ใบที่กำลังกรอกเหตุผลยืนยันส่ง — ทีละใบเท่านั้น (กล่องเหตุผลของสองใบพร้อมกัน = กรอกผิดใบ)
s.ordOvrText = ''; // เหตุผลที่หมอกำลังพิมพ์
s.ordOvrErr = ''; // เหตุผลสั้นเกิน/ว่าง — บอกที่จอก่อนยิง ไม่ให้ server เป็นคนตีกลับ

/* ══ ป้ายสถานะ — ชุดเดียวกับ pis-dispense D6 ═════════════════════════════
   🔴 ค่าที่ไม่รู้จักต้องโชว์ค่าดิบ ห้ามแปลงเป็น "ร่าง" — ใบที่สถานะเพี้ยน (เช่น "DRAFT" ตัวใหญ่)
      ต้องมองเห็นได้จากจอ ไม่ใช่ถูกกลบให้ดูปกติ */
const STATUS = {
	draft: { label: 'ร่าง', color: 'info' },
	sent: { label: 'ส่งห้องยาแล้ว', color: 'warning' },
	accepted: { label: 'ห้องยารับแล้ว', color: 'warning' },
	prepared: { label: 'จัดยาแล้ว', color: 'warning' },
	ready: { label: 'พร้อมจ่าย', color: 'success' },
	dispensed: { label: 'จ่ายยาแล้ว', color: 'success' },
	returned: { label: 'คืนยา', color: 'danger' },
	cancelled: { label: 'ยกเลิก', color: 'info' },
	reversed: { label: 'กลับรายการ', color: 'danger' },
};
s.ordStatus = (o) => {
	const raw = String((o && o.current_status) || '');
	return STATUS[raw] || { label: raw || '—', color: 'danger' };
};

s.ordMoney = (n) => '฿' + Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// created_at เป็น "YYYY-MM-DD HH:mm:ss" — ใบของวิสิทเดียวกันเกิดวันเดียวกันเกือบเสมอ จึงโชว์แค่เวลา
s.ordTime = (v) => {
	const t = String(v || '');
	return t.length >= 16 ? t.slice(11, 16) + ' น.' : t;
};

s.ordToggle = (id) => {
	s.ordOpenRow[id] = !s.ordOpenRow[id];
};

/* ══ โหลดใบของวิสิท ═══════════════════════════════════════════════════════
   เรียกจาก opd_card.setTran (เปลี่ยนคนไข้) · onMounted (เข้าแท็บ EMR ทีหลัง) · หลังปิด popup */
s.ordLoad = (visitId, tran) => {
	s.ordVid = visitId ? String(visitId) : null;
	if (tran !== undefined) s.ordTran = tran || null;
	s.ordList = [];
	s.ordErr = '';
	s.ordOpenRow = {};
	s.ordBlocks = {}; // คำเตือนของรอบก่อนต้องหายไปพร้อมรายการเก่า ไม่งั้นค้างทับใบที่แก้แล้ว
	s.ordOvrId = ''; // กล่องเหตุผลที่ค้างเปิดอยู่ต้องปิดตามด้วย — ใบเก่าอาจไม่อยู่ในลิสต์ใหม่แล้ว
	s.ordOvrText = '';
	s.ordOvrErr = '';
	if (!s.ordVid) return;
	const form = field.getFormRef();
	if (!form) return;
	s.ordLoading = true;
	form.userState.runProcess(
		LIST_PROC,
		{ visit_id: s.ordVid },
		(res) => {
			s.ordLoading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ ไม่ใช่ errCb — ต้องเช็คเอง
			if (!d.success) {
				s.ordErr = d.message || 'อ่านใบสั่งยาไม่สำเร็จ';
				return;
			}
			s.ordList = Array.isArray(d.orders) ? d.orders : [];
			// ใบร่างที่ยังแก้ได้ = สิ่งที่หมอต้องเห็นก่อน ⇒ กางให้เลยถ้ามีใบเดียว
			if (s.ordList.length === 1 && s.ordList[0].can_edit) s.ordOpenRow[s.ordList[0].order_id] = true;
		},
		(err) => {
			s.ordLoading = false;
			s.ordErr = 'อ่านใบสั่งยาไม่สำเร็จ: ' + ((err && err.message) || err);
		},
	);
};

s.ordReload = () => s.ordLoad(s.ordVid, undefined);

/* ══ patient context ที่จอสั่งยาต้องได้ครบ ════════════════════════════════
   🔴 จอสั่งยา "ห้าม query ซ้ำ" — ข้อมูลคนไข้/วิสิท/สิทธิ์/vitals ต้องส่งครบจากที่นี่ (D4.4)
      ตารางแปลงค่า (เพศ · หมู่เลือด · ชนิดบริการ · ระดับ warn/danger ของ vital) อยู่ที่ opd_card
      ที่เดียว — หยิบมาใช้ ห้ามทำชุดของตัวเอง ไม่งั้นวันหนึ่งสองจอจะเตือนคนละแบบ
   🔴 ส่งทาง `params` ไม่ใช่ `initData` — form_ui ที่มีแต่ vue-ui ตัด initData ทิ้งใน buildDataModel */
const ptContext = () => {
	const form = field.getFormRef();
	const card = field.getFieldRef('opd_card');
	const cs = (card && card.vueState) || {};
	const tran = s.ordTran || cs.tran || (form && form.$examTran) || null;
	const visit = (tran && tran.vid) || null;
	if (!visit) return null;

	const pt = visit.pid || {};
	const bmi = cs.bmiRec || {};
	const vs = cs.vsRec || {};
	const lvl = (name) => {
		if (typeof cs.vsClass !== 'function') return '';
		const c = cs.vsClass(name);
		return c === 'is-danger' ? 'bad' : c === 'is-warning' ? 'warn' : '';
	};
	const vital = (value, level) => (value === null || value === undefined || value === '' ? null : { value: value, level: level || '' });
	const bpValue = vs.bp_h && vs.bp_l ? String(vs.bp_h) + '/' + String(vs.bp_l) : '';
	const bpLevel = typeof cs.bpClass === 'function' ? (cs.bpClass() === 'is-danger' ? 'bad' : cs.bpClass() === 'is-warning' ? 'warn' : '') : '';

	return {
		person_id: visit.xtbxlv1_xfx_id ? String(visit.xtbxlv1_xfx_id) : '',
		hn: pt.hn || '',
		full_name: typeof cs.ptName === 'function' ? cs.ptName() : [pt.p_fname, pt.p_lname].filter(Boolean).join(' '),
		sex: typeof cs.genderLabel === 'function' ? cs.genderLabel() : '',
		age: pt.age == null ? '' : pt.age,
		blood_group: typeof cs.aboLabel === 'function' ? cs.aboLabel() : '',
		p_pic: pt.p_pic || null,
		allergy_tags: (tran && tran.allergy_tags) || [],
		visit_id: String(visit.value || visit._id || ''),
		vn: visit.vn || '',
		visit_type: typeof cs.serviceTypeLabel === 'function' ? cs.serviceTypeLabel() : '',
		visit_datetime: typeof cs.visitTime === 'function' ? cs.visitTime() : visit.visit_date || '',
		visit_clinic: (visit.visit_clinic || {}).label || '',
		visit_doctor: (visit.visit_doctor || {}).label || '',
		dx_summary: '',
		weight: bmi.weight == null ? '' : bmi.weight,
		height: bmi.stature == null ? '' : bmi.stature, // 🔴 ฟอร์ม BMI ใช้ชื่อ stature ไม่ใช่ height
		bmi: bmi.bmi == null ? '' : bmi.bmi,
		bsa: bmi.bsa == null ? '' : bmi.bsa,
		bp: vital(bpValue, bpLevel),
		pr: vital(vs.pulse, lvl('pulse')),
		temp: vital(vs.temp, lvl('temp')),
		rr: vital(vs.rr, lvl('rr')),
		service_type: 'med',
		inscl_hos: Array.isArray(visit.inscl_hos) ? visit.inscl_hos : [],
	};
};

/* เปิดจอสั่งยา — extra = { order_id } เมื่อเป็นการกลับเข้าไปแก้ใบเดิม

   🔴 refresh เฉพาะตอนที่ "ใบเปลี่ยนจริง" เท่านั้น (พี่แจ้ง 2026-08-04)
      cancelCallback เป็นทางออกทางเดียวของ popup — ทั้ง "กดปิดเฉย ๆ" และ "บันทึกแล้วปิด"
      (จอกด closePopup() ซึ่งวิ่งผ่าน cancelCallback ชุดนี้ · SdFormRender:1060) ⇒ ตัวมันเองแยกไม่ออก
      ⇒ ให้ "จอ" เป็นคนบอกผ่าน callback ที่ฝากไปกับ params — เปิดแล้วปิดเฉย ๆ จึงไม่ยิง process ฟรี
      (function ผ่าน params ได้จริง: formParams/vueParams เป็น shallow spread ทั้งคู่ ไม่ได้ clone ทิ้ง) */
const openScreen = (ctx, extra) => {
	const form = field.getFormRef();
	s.ordDirty = false;
	form.openForm(DRUG_ORDER_FORM_ID, '', String(ctx.visit_id), null, {
		backdrop: false, // ใบยาว — กดพลาดนอกกล่องแล้วปิดทิ้ง = เสียของที่เลือกไว้
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams, ctx, extra || {}, {
			// จอเรียกตัวนี้เมื่อ "แตะใบใน DB แล้ว" (บันทึกสำเร็จ หรือหัวใบเกิดแล้วรายการล้มกลางทาง)
			on_order_saved: () => {
				s.ordDirty = true;
			},
		}),
		// 🔴 ใส่ cancelCallback เอง = ทับ default ⇒ ต้อง subFormClose() เองด้วย
		cancelCallback: () => {
			form.subFormClose();
			if (!s.ordDirty) return; // ปิดเฉย ๆ — รายการในการ์ดยังตรงกับ DB อยู่แล้ว
			s.ordDirty = false;
			s.ordReload();
		},
	});
};

// ปุ่ม "+ สั่งยา" ที่หัวการ์ด — เปิดจอเปล่าเพื่อออกใบใหม่
s.ordNew = () => {
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, null));
};

// เปิดแก้ใบร่างเดิม — จอจะโหลดรายการกลับเป็นตะกร้าเองจาก order_id (process cpoe-order-get)
s.ordEdit = (o) => {
	if (!o || !o.order_id) return;
	if (!o.can_edit) {
		field.alert('ใบนี้ไม่ใช่ใบร่างแล้ว จึงแก้จากจอสั่งยาไม่ได้', 'warning');
		return;
	}
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, { order_id: String(o.order_id) }));
};

/* ส่งใบให้ห้องยา (draft → sent) — process ตัดสินทุกอย่างเอง จอไม่ตัดสินแทน

   🔴 ห้องยาปลายทางไม่ได้เลือกที่นี่ — process หาเองจาก mapping ที่ห้องยาตั้งไว้
      (stock_location.serve_units ประกาศว่าคลังนั้นรับใบจากคลินิกไหน) ⇒ อย่าเพิ่มช่องให้หมอเลือก
   🔴 คำเตือนระดับ block ที่ตีกลับมา ต้องแปะไว้ในการ์ด ไม่ใช่ alert ที่กดปิดแล้วหาย —
      หมอต้องอ่านได้ว่าติดตัวไหน ระหว่างเปิดจอไปแก้
   🔴 ห้าม `await` ในไฟล์นี้ — ปุ่มเป็น sync handler ⇒ ใช้ callback ของ runProcess เท่านั้น

   ── override (C31) ────────────────────────────────────────────────────
   ติด block แล้ว "แก้ไม่ได้จริง" มีอยู่จริงในทางคลินิก (ไม่มียาแทน · ประวัติแพ้ไม่ชัด)
   ระบบที่บล็อกสนิทจะโดนหาทางอ้อม (สั่งด้วยวาจา/กระดาษ) แล้วไม่เหลือร่องรอยในระบบเลย
   ⇒ ให้ทางออกที่ **บันทึกได้**: กรอกเหตุผล ≥ MIN_OVR ตัวอักษร แล้วยิงซ้ำพร้อม override_reason
   🔴 เกณฑ์ความยาวต้องตรงกับ MIN_OVERRIDE_REASON ใน cpoe-order-send (พี่เคาะ 10 · 2026-08-07)
      เช็คที่จอด้วยเพื่อบอกก่อนกด — ไม่ใช่ให้หมอพิมพ์เสร็จแล้วโดน server ตีกลับ */
const MIN_OVR = 10;
s.ordOvrMin = MIN_OVR; // เทมเพลตอ่านค่านี้ ห้าม hardcode เลขซ้ำในจอ (สองที่หลุดกันเมื่อไหร่ = จอบอกเกณฑ์ผิด)

s.ordOvrLen = () => String(s.ordOvrText || '').trim().length;
// setter แยก — เทมเพลตใช้ :value + @input เหมือนช่องอื่นในระบบ ไม่ใช้ v-model / assignment ใน template
s.ordOvrInput = (v) => {
	s.ordOvrText = String(v == null ? '' : v);
	if (s.ordOvrErr) s.ordOvrErr = ''; // พิมพ์ต่อ = ข้อความ error ของรอบก่อนหมดอายุแล้ว
};

// ปิดกล่องเหตุผล — ใช้ทั้งตอนกดยกเลิกและตอนส่งสำเร็จ
s.ordOvrClose = () => {
	s.ordOvrId = '';
	s.ordOvrText = '';
	s.ordOvrErr = '';
};

/* ยิง process จริง — reason ว่าง = ส่งปกติ · มีค่า = ยืนยันส่งทั้งที่ติด block
   🔴 ไม่ส่ง key override_reason เลยเมื่อไม่มีเหตุผล (backend ถือว่า "ไม่ override" ตามพฤติกรรมเดิม) */
const sendOrder = (id, reason) => {
	const form = field.getFormRef();
	if (!form) return;
	s.ordSending[id] = true;
	s.ordBlocks[id] = [];
	const args = { order_id: id };
	if (reason) args.override_reason = reason;
	form.userState.runProcess(
		SEND_PROC,
		args,
		(res) => {
			s.ordSending[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				// รายการที่ติดกฎห้ามสั่ง — แปะไว้ในการ์ดให้อ่านต่อได้ ส่วนเหตุผลอื่นบอกเป็น alert พอ
				if (Array.isArray(d.blocks) && d.blocks.length) s.ordBlocks[id] = d.blocks;
				if (d.code === 'HAS_BLOCK' || d.code === 'OVERRIDE_REASON_TOO_SHORT') {
					// เปิดกล่องเหตุผลค้างไว้ให้กรอกต่อ — ที่พิมพ์ไปแล้วต้องไม่หาย
					s.ordOvrId = id;
					s.ordOvrErr = d.code === 'OVERRIDE_REASON_TOO_SHORT' ? d.message || '' : '';
					// 🔴 ไม่ ordReload() ตรงนี้ — โหลดใหม่ = ลิสต์ถูกสร้างใหม่ กล่องที่เพิ่งเปิดจะกระพริบ
					return;
				}
				field.alert(d.message || 'ส่งใบสั่งยาไม่สำเร็จ', 'warning');
				s.ordReload(); // สถานะอาจเปลี่ยนไปแล้วจากอีกจอ — ให้การ์ดตรงกับ DB เสมอ
				return;
			}
			s.ordOvrClose();
			field.alert(d.message || 'ส่งใบสั่งยาแล้ว', 'success');
			s.ordReload();
		},
		(err) => {
			s.ordSending[id] = false;
			field.alert('ส่งใบสั่งยาไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

// ปุ่ม "ส่งใบสั่งยา" ปกติ (ผ่าน el-popconfirm)
s.ordSend = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.ordSending[id]) return;
	if (String(o.current_status || '') !== 'draft') {
		field.alert('ใบนี้ถูกส่งไปแล้ว', 'warning');
		return;
	}
	s.ordOvrClose(); // กดส่งใหม่ = เริ่มรอบใหม่ เหตุผลของรอบก่อนต้องไม่ติดมา
	sendOrder(id, '');
};

// ปุ่ม "ยืนยันส่งพร้อมเหตุผล" ในกล่อง override
s.ordOvrSubmit = (o) => {
	const id = String((o && o.order_id) || s.ordOvrId || '');
	if (!id || s.ordSending[id]) return;
	const reason = String(s.ordOvrText || '').trim();
	if (reason.length < MIN_OVR) {
		s.ordOvrErr = 'ระบุเหตุผลอย่างน้อย ' + MIN_OVR + ' ตัวอักษร (ตอนนี้ ' + reason.length + ')';
		return;
	}
	s.ordOvrErr = '';
	sendOrder(id, reason);
};

/* สิทธิ์ของวิสิท (D9 ข้อ 1) — joiner `vid` ของ Visit Tran ยังไม่ได้ดึง inscl_hos[] มาให้
   ไม่มีสิทธิ์ = จอคิดเป็นชำระเองทั้งใบ ⇒ อ่านจาก joiner ก่อน ไม่มีค่อย query visit ทีเดียว */
function withInscl(ctx, done) {
	if (Array.isArray(ctx.inscl_hos) && ctx.inscl_hos.length) {
		done(ctx);
		return;
	}
	const form = field.getFormRef();
	form.userState.crudGetAll(
		{
			sdProvider: {
				providerId: VISIT_PROVIDER,
				providerType: 'FORM',
				params: { vid: String(ctx.visit_id) },
				options: { where: "_id = CONVERT(:vid, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => {
			const rec = (res && res.data && res.data[0]) || null;
			ctx.inscl_hos = (rec && rec.inscl_hos) || [];
			done(ctx);
		},
		() => {
			field.alert('อ่านสิทธิ์ของวิสิทไม่สำเร็จ — จอสั่งยาจะคิดเป็นชำระเองทั้งใบ', 'warning');
			done(ctx);
		},
	);
}

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ EMR mount หลังกดเลือกคนไข้จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับ registry_card)
setTimeout(() => {
	const form = field.getFormRef();
	const tran = form && form.$examTran;
	const visitId = tran && tran.vid && tran.vid.value ? String(tran.vid.value) : null;
	s.ordLoad(visitId, tran || null);
}, 0);

options.onCreated:
const s = this.vueState;
const field = this;

const CENTER_LAB_FORM_ID = '6a75a7810796231c653df996';
const VISIT_PROVIDER = '6a40fdec4b6dfdf45acbfbce'; // ฟอร์ม Visit → zdata_visit

s.labOrdList = [];
s.labOrdLoading = false;
s.labOrdErr = '';
s.labOrdVid = null;
s.labOrdTran = null; // Visit Tran ทั้งแถว (ใช้ประกอบ patient context ตอนเปิดจอสั่งแลป)
s.labOrdOpenRow = {};

s.labOrdMoney = (n) => '฿' + Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
s.labOrdTime = (v) => {
  const t = String(v || '');
  return t.length >= 16 ? t.slice(0, 16).replace('T', ' ') : t;
};
s.labOrdToggle = (id) => { s.labOrdOpenRow[id] = !s.labOrdOpenRow[id]; };
s.labOrdTotal = (o) => (o.items || []).reduce((sum, it) => sum + (Number(it.sale_price) || 0), 0);

/* โหลดใบของวิสิท — เรียกจาก opd_card.setTran (เปลี่ยนคนไข้) · onMounted (เข้าแท็บ EMR ทีหลัง) · หลังปิด popup */
s.labOrdLoad = (visitId, tran) => {
  s.labOrdVid = visitId ? String(visitId) : null;
  if (tran !== undefined) s.labOrdTran = tran || null;
  s.labOrdList = [];
  s.labOrdErr = '';
  s.labOrdOpenRow = {};
  if (!s.labOrdVid) return;
  const form = field.getFormRef();
  if (!form) return;
  s.labOrdLoading = true;
  form.userState.crudGetAll(
    {
      sdProvider: {
        providerId: CENTER_LAB_FORM_ID,
        providerType: 'FORM',
        params: { vid: s.labOrdVid },
        options: {
          where: 'visit_id_link = :vid',
          orderBy: [{ column: 'created_at', sort: 'DESC' }],
          limit: 50,
          page: 1,
        },
      },
      totalEnable: false,
    },
    (res) => {
      s.labOrdLoading = false;
      const rows = (res && res.data) || [];
      s.labOrdList = rows.map((rec) => {
        let groups = [];
        try { groups = JSON.parse(rec.selected_items_json || '[]'); } catch (e) { groups = []; }
        const items = Array.isArray(groups)
          ? groups.reduce((acc, g) => acc.concat((g && Array.isArray(g.selected_items)) ? g.selected_items : []), [])
          : [];
        return { _id: rec._id, created_at: rec.created_at, items: items };
      });
    },
    (err) => {
      s.labOrdLoading = false;
      s.labOrdErr = 'อ่านใบสั่งแลปไม่สำเร็จ: ' + ((err && err.message) || err);
    },
  );
};

s.labOrdReload = () => s.labOrdLoad(s.labOrdVid, undefined);

/* patient context ที่จอสั่งแลปต้องได้ครบ — รูปแบบเดียวกับ order_card.ptContext()
   pt_header ของฟอร์มลูกอ่านผ่าน field.params ไม่ใช่ formModel */
const ptContext = () => {
  const form = field.getFormRef();
  const card = field.getFieldRef('opd_card');
  const cs = (card && card.vueState) || {};
  const tran = s.labOrdTran || cs.tran || (form && form.$examTran) || null;
  const visit = (tran && tran.vid) || null;
  if (!visit) return null;

  const pt = visit.pid || {};
  const bmi = cs.bmiRec || {};
  const vs = cs.vsRec || {};
  const lvl = (name) => {
    if (typeof cs.vsClass !== 'function') return '';
    const c = cs.vsClass(name);
    return c === 'is-danger' ? 'bad' : c === 'is-warning' ? 'warn' : '';
  };
  const vital = (value, level) => (value === null || value === undefined || value === '' ? null : { value: value, level: level || '' });
  const bpValue = vs.bp_h && vs.bp_l ? String(vs.bp_h) + '/' + String(vs.bp_l) : '';
  const bpLevel = typeof cs.bpClass === 'function' ? (cs.bpClass() === 'is-danger' ? 'bad' : cs.bpClass() === 'is-warning' ? 'warn' : '') : '';

  return {
    hn: pt.hn || '',
    full_name: typeof cs.ptName === 'function' ? cs.ptName() : [pt.p_fname, pt.p_lname].filter(Boolean).join(' '),
    sex: typeof cs.genderLabel === 'function' ? cs.genderLabel() : '',
    age: pt.age == null ? '' : pt.age,
    blood_group: typeof cs.aboLabel === 'function' ? cs.aboLabel() : '',
    p_pic: pt.p_pic || null,
    allergy_tags: (tran && tran.allergy_tags) || [],
    visit_id: String(visit.value || visit._id || ''),
    vn: visit.vn || '',
    visit_type: typeof cs.serviceTypeLabel === 'function' ? cs.serviceTypeLabel() : '',
    visit_datetime: typeof cs.visitTime === 'function' ? cs.visitTime() : visit.visit_date || '',
    visit_clinic: (visit.visit_clinic || {}).label || '',
    visit_doctor: (visit.visit_doctor || {}).label || '',
    weight: bmi.weight == null ? '' : bmi.weight,
    height: bmi.stature == null ? '' : bmi.stature,
    bmi: bmi.bmi == null ? '' : bmi.bmi,
    bsa: bmi.bsa == null ? '' : bmi.bsa,
    bp: vital(bpValue, bpLevel),
    pr: vital(vs.pulse, lvl('pulse')),
    temp: vital(vs.temp, lvl('temp')),
    rr: vital(vs.rr, lvl('rr')),
    inscl_hos: Array.isArray(visit.inscl_hos) ? visit.inscl_hos : [],
  };
};

/* สิทธิ์ของวิสิท — joiner `vid` ของ Visit Tran ยังไม่ได้ดึง inscl_hos[] มาให้
   ไม่มีสิทธิ์ = จอคิดเป็นชำระเองทั้งใบ ⇒ อ่านจาก joiner ก่อน ไม่มีค่อย query visit ทีเดียว
   (ชุดเดียวกับ order_card.withInscl — คัดลอกมาเพราะ pt_header ของจอสั่งแลปต้องการ chip นี้เหมือนกัน) */
function withInscl(ctx, done) {
  // จอจิง — vid joiner ไม่เชื่อถือทั้ง inscl_hos[]/vn/visit_date เหมือนกัน — เช็คทุกตัวก่อนข้าม query ไม่ใช่แค่ inscl_hos ตัวเดียว
  const hasInscl = Array.isArray(ctx.inscl_hos) && ctx.inscl_hos.length;
  if (hasInscl && ctx.vn && ctx.visit_datetime) {
    done(ctx);
    return;
  }
  const form = field.getFormRef();
  form.userState.crudGetAll(
    {
      sdProvider: {
        providerId: VISIT_PROVIDER,
        providerType: 'FORM',
        params: { vid: String(ctx.visit_id) },
        options: { where: "_id = CONVERT(:vid, 'objectId')", limit: 1, page: 1 },
      },
      totalEnable: false,
    },
    (res) => {
      const rec = (res && res.data && res.data[0]) || null;
      if (!hasInscl) ctx.inscl_hos = (rec && rec.inscl_hos) || [];
      if (!ctx.vn) ctx.vn = (rec && rec.vn) || '';
      if (!ctx.visit_datetime) ctx.visit_datetime = (rec && rec.visit_date) || '';
      done(ctx);
    },
    () => {
      field.alert('อ่านข้อมูลวิสิทเพิ่มเติมไม่สำเร็จ — จอสั่งแลปจะแสดงเท่าที่มีจาก joiner', 'warning');
      done(ctx);
    },
  );
}

const openScreen = (ctx) => {
  const form = field.getFormRef();
  form.openForm(CENTER_LAB_FORM_ID, null, String(ctx.visit_id), undefined, {
    // ส่งทาง params ไม่ใช่ initData - form_ui ที่มีแต่ vue-ui ตัด initData ทิ้งใน buildDataModel
    params: Object.assign({}, form.formParams, ctx),
    afterSaveCallback: () => {
      form.subFormClose();
      s.labOrdReload();
    },
  });
};

// ปุ่ม "+ สั่งแลป" ที่หัวการ์ด — เปิดจอเปล่าเพื่อออกใบใหม่ (สั่งแลปได้หลายใบต่อวิสิท)
s.labOrdNew = () => {
  const ctx = ptContext();
  if (!ctx || !ctx.visit_id) {
    field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
    return;
  }
  withInscl(ctx, (full) => openScreen(full));
};

